  test(
    'test probes a live stub endpoint and reports ok with the latency',
    () async {
      final server = await HttpServer.bind('127.0.0.1', 0);
      addTearDown(server.close);
      server.listen((request) async {
        // A minimal SSE stream: one delta, then [DONE].
        request.response.headers.contentType = ContentType(
          'text',
          'event-stream',
        );
        const id = 'chatcmpl-probe';
        final parts = [
          {
            'id': id,
            'object': 'chat.completion.chunk',
            'created': 1,
            'model': 'queue-x',
            'choices': [
              {
                'index': 0,
                'delta': {'role': 'assistant'},
                'finish_reason': null,
              },
            ],
          },
          {
            'id': id,
            'object': 'chat.completion.chunk',
            'created': 1,
            'model': 'queue-x',
            'choices': [
              {
                'index': 0,
                'delta': {'content': 'pong'},
                'finish_reason': null,
              },
            ],
          },
          {
            'id': id,
            'object': 'chat.completion.chunk',
            'created': 1,
            'model': 'queue-x',
            'choices': [
              {
                'index': 0,
                'delta': <String, dynamic>{},
                'finish_reason': 'stop',
              },
            ],
          },
        ];
        for (final part in parts) {
          request.response.add(utf8.encode('data: ${jsonEncode(part)}\n\n'));
        }
        request.response.add(utf8.encode('data: [DONE]\n\n'));
        await request.response.close();
      });

      final keyless =
          '''
provider: openai-completions
model: test-model
baseUrl: http://127.0.0.1:1/v1
providersQueue:
  - provider_type: openai-completions
    provider_config:
      model: queue-x
      apiKeyEnv: K_X
      baseUrl: http://127.0.0.1:${server.port}/v1
''';
      File('${home.path}/.fah/config.yaml').writeAsStringSync(keyless);
